INSERT INTO _p5_v3_empty_gate SELECT
 (SELECT count(*) FROM authority_proposals)+
 (SELECT count(*) FROM authority_transitions)+
 (SELECT count(*) FROM logical_trials)+
 (SELECT count(*) FROM trial_attempts)+
 (SELECT count(*) FROM owner_conditional_delegations)+
 (SELECT count(*) FROM delegation_redemptions)+
 (SELECT count(*) FROM owner_delegation_revocations)+
 (SELECT count(*) FROM amendment_registrations);
